import {
	bytesToHex,
	consensusIdenticalAggregation,
	cre,
	type CronPayload,
	getNetwork,
	type HTTPSendRequester,
	type Runtime,
	TxStatus,
} from '@chainlink/cre-sdk'
import {
	type Address,
	encodeAbiParameters,
	type Hex,
	keccak256,
	parseAbiParameters,
	toBytes,
	zeroAddress,
	zeroHash,
} from 'viem'
import { z } from 'zod'
// Generated by `cre generate-bindings evm` from contracts/evm/src/abi/PayeeRegistry.abi
import {
	PayeeRegistry,
	type DecodedLog,
	type RegistrationRequestedDecoded,
} from '../contracts/evm/ts/generated/PayeeRegistry'

// ─── Config ─────────────────────────────────────────────────
export const configSchema = z.object({
	chainSelectorName: z.string(), // "arc-testnet"
	registryAddress: z.string(),
	schedule: z.string(), // daily re-check, e.g. "0 0 * * *"
	requireDnssec: z.boolean(), // true in production; false if the demo domain has no DNSSEC
	gasLimit: z.string().optional(),
})
type Config = z.infer<typeof configSchema>

const ACTION_VERIFY = 1
const ACTION_FREEZE = 2
// PayeeRegistry.Status
const STATUS_PENDING = 1
const STATUS_ACTIVE = 2
const STATUS_FROZEN = 3

// ─── DNS-over-HTTPS (two independent resolvers) ─────────────
type DnsResult = {
	ok: boolean // resolver answered
	ad: boolean // DNSSEC validated
	controller: string // "" if no valid arc: record
	lei: string // "" if no lei: record
}

type DnsRequest = { url: string; accept: string }

const parseTxt = (body: any): DnsResult => {
	const answers: Array<{ type: number; data: string }> = body?.Answer ?? []
	let controller = ''
	let lei = ''
	for (const a of answers) {
		if (a.type !== 16) continue // TXT
		const txt = String(a.data).replace(/^"+|"+$/g, '').replace(/"\s*"/g, '')
		const c = txt.match(/^arc:(0x[0-9a-fA-F]{40})$/)
		if (c) controller = c[1].toLowerCase()
		const l = txt.match(/^lei:([0-9A-Z]{20})$/)
		if (l) lei = l[1]
	}
	return { ok: body?.Status === 0, ad: body?.AD === true, controller, lei }
}

// Runs on every DON node; consensusIdenticalAggregation requires all nodes to agree.
export const fetchTxt = (sendRequester: HTTPSendRequester, req: DnsRequest): DnsResult => {
	const res = sendRequester
		.sendRequest({ url: req.url, method: 'GET', headers: { accept: req.accept } })
		.result()
	if (res.statusCode !== 200) throw new Error(`DoH HTTP ${res.statusCode}`)
	return parseTxt(JSON.parse(Buffer.from(res.body).toString('utf-8')))
}

// ─── GLEIF (optional LEI check) ─────────────────────────────
type LeiResult = { issued: boolean }

export const fetchLei = (sendRequester: HTTPSendRequester, lei: string): LeiResult => {
	const res = sendRequester
		.sendRequest({
			url: `https://api.gleif.org/api/v1/lei-records/${lei}`,
			method: 'GET',
			headers: { accept: 'application/vnd.api+json' },
		})
		.result()
	if (res.statusCode !== 200) return { issued: false }
	const body = JSON.parse(Buffer.from(res.body).toString('utf-8'))
	const a = body?.data?.attributes
	return { issued: a?.registration?.status === 'ISSUED' && a?.entity?.status === 'ACTIVE' }
}

// ─── Core decision ──────────────────────────────────────────
type Decision = { action: number; controller: Address; leiHash: Hex; reason: string } | null

const decide = (runtime: Runtime<Config>, domain: string, status: number): Decision => {
	const http = new cre.capabilities.HTTPClient()
	const name = `_verifypay.${domain}`
	const google = http
		.sendRequest(runtime, fetchTxt, consensusIdenticalAggregation<DnsResult>())({
			url: `https://dns.google/resolve?name=${name}&type=TXT`,
			accept: 'application/dns-json',
		})
		.result()
	const cloudflare = http
		.sendRequest(runtime, fetchTxt, consensusIdenticalAggregation<DnsResult>())({
			url: `https://cloudflare-dns.com/dns-query?name=${name}&type=TXT`,
			accept: 'application/dns-json',
		})
		.result()
	runtime.log(`${domain}: google=${JSON.stringify(google)} cloudflare=${JSON.stringify(cloudflare)}`)

	const agree =
		google.ok && cloudflare.ok && google.controller !== '' && google.controller === cloudflare.controller
	const dnssecOk = !runtime.config.requireDnssec || (google.ad && cloudflare.ad)

	let leiHash: Hex = zeroHash
	let leiOk = true
	if (agree && google.lei !== '' && google.lei === cloudflare.lei) {
		const lei = http
			.sendRequest(runtime, fetchLei, consensusIdenticalAggregation<LeiResult>())(google.lei)
			.result()
		leiOk = lei.issued
		leiHash = keccak256(toBytes(google.lei))
	}

	if (agree && dnssecOk && leiOk) {
		// The registry itself freezes + time-locks if this controller differs from the stored one.
		return { action: ACTION_VERIFY, controller: google.controller as Address, leiHash, reason: 'dns-match' }
	}
	if (status === STATUS_ACTIVE) {
		const reason = !agree ? 'dns-missing-or-mismatch' : !dnssecOk ? 'dnssec-failed' : 'lei-lapsed'
		return { action: ACTION_FREEZE, controller: zeroAddress, leiHash: zeroHash, reason }
	}
	return null // Pending or already Frozen: nothing to write
}

const writeDecision = (runtime: Runtime<Config>, registry: PayeeRegistry, domainHash: Hex, d: Decision): string => {
	if (!d) return 'no-op'
	const report = encodeAbiParameters(
		parseAbiParameters('bytes32 domainHash, address controller, bytes32 leiHash, uint8 action'),
		[domainHash, d.controller, d.leiHash, d.action],
	)
	const resp = registry.writeReport(runtime, report, { gasLimit: runtime.config.gasLimit ?? '500000' })
	if (resp.txStatus !== TxStatus.SUCCESS) {
		throw new Error(`onReport tx failed: ${resp.errorMessage ?? resp.txStatus}`)
	}
	const txHash = bytesToHex(resp.txHash ?? new Uint8Array(32))
	runtime.log(`action=${d.action} (${d.reason}) tx=${txHash}`)
	return txHash
}

const registryFor = (config: Config): PayeeRegistry => {
	const network = getNetwork({ chainFamily: 'evm', chainSelectorName: config.chainSelectorName, isTestnet: true })
	if (!network) throw new Error(`Network not found: ${config.chainSelectorName}`)
	const evm = new cre.capabilities.EVMClient(network.chainSelector.selector)
	return new PayeeRegistry(evm, config.registryAddress as Address)
}

// ─── Trigger 0: new registration request (EVM log) ──────────
export const onRegistrationRequested = (
	runtime: Runtime<Config>,
	log: DecodedLog<RegistrationRequestedDecoded>,
): string => {
	const { domainHash, domain } = log.data
	if (keccak256(toBytes(domain)) !== domainHash) throw new Error('domain/hash mismatch')
	const registry = registryFor(runtime.config)
	const payee = registry.getPayee(runtime, domainHash)
	const d = decide(runtime, domain, Number(payee.status))
	return writeDecision(runtime, registry, domainHash, d)
}

// ─── Trigger 1: daily re-check of every payee (cron) ────────
export const onDailyRecheck = (runtime: Runtime<Config>, _payload: CronPayload): string => {
	const registry = registryFor(runtime.config)
	const count = Number(registry.domainCount(runtime))
	const results: string[] = []
	for (let i = 0; i < count; i++) {
		const [domainHash, domain, status] = registry.domainAt(runtime, BigInt(i))
		const s = Number(status)
		if (s !== STATUS_ACTIVE && s !== STATUS_FROZEN && s !== STATUS_PENDING) continue
		results.push(`${domain}:${writeDecision(runtime, registry, domainHash, decide(runtime, domain, s))}`)
	}
	return results.join(',')
}

export function initWorkflow(config: Config) {
	const registry = registryFor(config)
	const cron = new cre.capabilities.CronCapability()
	return [
		cre.handler(registry.logTriggerRegistrationRequested(), onRegistrationRequested),
		cre.handler(cron.trigger({ schedule: config.schedule }), onDailyRecheck),
	]
}
